impl Solution{pub fn is_interleave(a:String,b:String,c:String)->bool{let(a,b,c)=(a.as_bytes(),b.as_bytes(),c.as_bytes());if c.len()!=a.len()+b.len(){return false}let mut d=vec![false;b.len()+1];d[0]=true;for j in 1..=b.len(){d[j]=d[j-1]&&b[j-1]==c[j-1]}for i in 1..=a.len(){d[0]=d[0]&&a[i-1]==c[i-1];for j in 1..=b.len(){d[j]=(d[j]&&a[i-1]==c[i+j-1])||(d[j-1]&&b[j-1]==c[i+j-1]);}}d[b.len()]}}
